def transforms(S):
    import itertools
    pts=list(S)
    res={}
    for name,f in [('id',lambda r,c:(r,c)),('rot90',lambda r,c:(c,5-r)),('rot180',lambda r,c:(5-r,4-c)),('rot270',lambda r,c:(4-c,r)),
                   ('fliph',lambda r,c:(r,4-c)),('flipv',lambda r,c:(5-r,c)),('tr',lambda r,c:(c,r)),('tl',lambda r,c:(4-c,5-r))]:
        res[name]={f(r,c) for r,c in pts}
    return res
